import{_ as p,a0 as r,w as l,s as d,ao as o,I as n,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何從 Debian 穩定版切換到測試版 | LCTT x X-CMD","titleTemplate":false,"description":"如何從 Debian 穩定版切換到測試版 | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何從 Debian 穩定版切換到測試版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何從 Debian 穩定版切換到測試版 | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221215.0 ⭐️⭐️ How to Switch from Debian Stable to Testing","title":"如何從 Debian 穩定版切換到測試版","tag":"202302","desc":""},"relativePath":"202302/20221215.0 ⭐️⭐️ How to Switch from Debian Stable to Testing.md","filePath":"[post].md"}'),g={name:"202302/20221215.0 ⭐️⭐️ How to Switch from Debian Stable to Testing.md"};function b(u,s,h,k,m,f){const e=r("Link");return l(),d("div",null,[s[28]||(s[28]=o('<h1 id="如何從-debian-穩定版切換到測試版" tabindex="-1">如何從 Debian 穩定版切換到測試版 <a class="header-anchor" href="#如何從-debian-穩定版切換到測試版" aria-label="Permalink to “如何從 Debian 穩定版切換到測試版”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202302/08/122659a4919hso9onkbmun.jpg" alt=""></p><p>如果你正在尋找最穩定的 Linux 發行版，當然，Debian 是正確的選擇。</p><p>特別是如果你打算在服務器上使用它。</p><p>但是，在桌面方面，情況就有點不同了。我的意思是，你得到的軟件包至少是一年前的，對新時代硬件的支持甚至更糟。</p><p>那麼，在這種情況下，你會怎麼做呢？好吧，你可以使用 Debian <ruby>測試版<rt>Testing</rt></ruby>。</p><p>但在跳到解釋部分之前，讓我們簡單瞭解一下 Debian 測試版。</p><h3 id="什麼是-debian-測試版" tabindex="-1">什麼是 Debian 測試版？ <a class="header-anchor" href="#什麼是-debian-測試版" aria-label="Permalink to “什麼是 Debian 測試版？”">​</a></h3><p>Debian 社區為你提供 3 種不同的 Debian：</p><ul><li>Debian <ruby>穩定版<rt>Stable</rt></ruby>（你從他們的主頁上默認得到的東西）。</li><li>Debian <ruby>測試版<rt>Testing</rt></ruby>（有<strong>新的軟件包</strong>，比 Debian 不穩定版更少出現故障）。</li><li>Debian <ruby>不穩定版<rt>Unstable</rt></ruby>（擁有最新的軟件包，是<strong>所有版本中最脆弱的</strong>）。</li></ul><p>因此，Debian 測試版可以被認為是穩定性和新軟件包之間的一個折中點。</p><p>我已經玩了一段時間的 Debian 測試版，沒有遇到任何問題。</p><p>事實上，許多 Debian 用户喜歡測試版而不是穩定版。儘管名字叫“測試”，但它是相當可用的。</p><p>但是，<strong>我還是建議你在虛擬機上進行實驗</strong>，嘗試用你的主要工具來使用它，如果事情進展順利，你可以在主系統中應用這些變化。</p><h3 id="從-debian-穩定版切換到-debian-測試版" tabindex="-1">從 Debian 穩定版切換到 Debian 測試版 <a class="header-anchor" href="#從-debian-穩定版切換到-debian-測試版" aria-label="Permalink to “從 Debian 穩定版切換到 Debian 測試版”">​</a></h3><p><strong>警告：你不能從 Debian 測試版降級到 Debian 穩定版，因為安裝腳本和安裝工具只是為了用新版本替換舊版本而設計的。</strong></p>',16)),n("p",null,[s[1]||(s[1]=t("另外，我建議在你的主機上應用上述步驟之前，",-1)),i(e,{href:"https://itsfoss.com/backup-restore-linux-timeshift/"},{default:a(()=>[...s[0]||(s[0]=[t("使用 timeshift 創建一個備份",-1)])]),_:1}),s[2]||(s[2]=t(" 。",-1))]),s[29]||(s[29]=o('<p>首先，使用給定的命令更新現有的軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade -y</span></span></code></pre></div><p>接下來，複製原始的 <code>sources.list</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/apt/sources.list sources.list.backup</span></span></code></pre></div><p>現在，讓我們開始第一步的工作。</p><h4 id="步驟-1-編輯-sources-list-文件" tabindex="-1">步驟 1：編輯 sources.list 文件 <a class="header-anchor" href="#步驟-1-編輯-sources-list-文件" aria-label="Permalink to “步驟 1：編輯 sources.list 文件”">​</a></h4>',6)),n("p",null,[s[4]||(s[4]=t("有兩種方法可以編輯 ",-1)),s[5]||(s[5]=n("code",null,"sources.list",-1)),s[6]||(s[6]=t(" 文件。要麼你可以用 ",-1)),s[7]||(s[7]=n("code",null,"testing",-1)),s[8]||(s[8]=t(" 手動改變當前版本的名稱，要麼你可以 ",-1)),i(e,{href:"https://linuxhandbook.com/sed-command-basics/"},{default:a(()=>[...s[3]||(s[3]=[t("使用 sed 命令",-1)])]),_:1}),s[9]||(s[9]=t(" 來完成。",-1))]),s[30]||(s[30]=o('<p>而我要用第二種方法來使整個過程更簡單。你只需要使用給定的命令，它就會為你把 <code>bullseye</code> 替換成 <code>testing</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo sed -i &#39;s/bullseye/testing/g&#39; /etc/apt/sources.list</span></span></code></pre></div><p>現在，打開你的終端，使用給定的命令來打開 <code>sources.list</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/apt/sources.list</span></span></code></pre></div><p>並註釋掉有 <code>security.debian.org</code> 和任何以 <code>updates</code> 結尾的行，如下所示：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/comment-out-security-sources.gif" alt="comment out security sources"></p><p>如果你像我一樣使用 <code>nano</code>，你可以按 <code>Alt + /</code> 跳到該行的最後。然後你要添加以下一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://security.debian.org testing-security main</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/2.-add-line-to-keep-track-of-testing-in-debian.png" alt="add line to keep track of testing in debian"></p>',9)),n("p",null,[s[11]||(s[11]=t("然後 ",-1)),i(e,{href:"https://linuxhandbook.com/nano-save-exit/"},{default:a(()=>[...s[10]||(s[10]=[t("保存修改並退出 nano",-1)])]),_:1}),s[12]||(s[12]=t(" 文本編輯器。",-1))]),s[31]||(s[31]=o('<h4 id="步驟-2-更新倉庫並安裝新的軟件包" tabindex="-1">步驟 2：更新倉庫並安裝新的軟件包 <a class="header-anchor" href="#步驟-2-更新倉庫並安裝新的軟件包" aria-label="Permalink to “步驟 2：更新倉庫並安裝新的軟件包”">​</a></h4><p>現在，更新倉庫索引，它會顯示大量的更新等待：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/update-repository-in-linux.png" alt="update repository in linux"></p><p>現在，你可以使用給定的命令，它將為你提供最新的軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt upgrade</span></span></code></pre></div><p>坐下來，放鬆一下，因為這將需要一些時間。</p><p>完成後，它將向你展示從 Debian 穩定版切換到測試版時的變化列表：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/packages-that-are-updated-when-switched-to-debian-testing.png" alt="packages that are updated when switched to debian testing"></p><p>如果你願意，你可以閲讀，或者你可以<strong>直接按</strong> <code>q</code> 繼續。</p><p>現在，它會告訴你，你係統上安裝的一些庫需要重新啓動。按 <code>TAB</code> 鍵，它將選擇 “OK”，然後按<strong>回車</strong>：。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/libraries-needs-to-be-restarted-after-update.png" alt="libraries needs to be restarted after update"></p><p>接下來，它會問你是否要在軟件包升級期間重啓服務。這裏你有一個選擇。由於我只做桌面使用，我將選擇 “YES”。</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/restart-services-during-package-upgrades-without-asking.png" alt="restart services during package upgrades without asking?"></p><p>完成後，你可以重啓你的系統，然後使用下面的命令，讓你剛才的改變完全生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt full-upgrade</span></span></code></pre></div><p>現在，重啓你的系統，你就會擁有最新的軟件包。比如<strong>我進入系統時我在運行 GNOME 43</strong>：</p><p><img src="https://itsfoss.com/content/images/wordpress/2022/11/running-gnome-43-in-debian.png" alt="running gnome 43 in debian"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在本教程中，我解釋瞭如何從 Debian 穩定版切換到 Debian 測試版。我希望這對你會有幫助。</p><p>如果你遇到任何問題或有任何疑問，請在評論中告訴我。</p><hr>',22)),n("p",null,[s[14]||(s[14]=t("via: ",-1)),i(e,{href:"https://itsfoss.com/switch-debian-stable-testing/"},{default:a(()=>[...s[13]||(s[13]=[t("https://itsfoss.com/switch-debian-stable-testing/",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=t("作者：",-1)),i(e,{href:"https://itsfoss.com/author/sagar/"},{default:a(()=>[...s[15]||(s[15]=[t("Sagar Sharma",-1)])]),_:1}),s[20]||(s[20]=t(" 選題：",-1)),i(e,{href:"https://github.com/lkxed"},{default:a(()=>[...s[16]||(s[16]=[t("lkxed",-1)])]),_:1}),s[21]||(s[21]=t(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...s[17]||(s[17]=[t("geekpi",-1)])]),_:1}),s[22]||(s[22]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[18]||(s[18]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[25]||(s[25]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[23]||(s[23]=[t("LCTT",-1)])]),_:1}),s[26]||(s[26]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[24]||(s[24]=[t("Linux中國",-1)])]),_:1}),s[27]||(s[27]=t(" 榮譽推出",-1))])])}const D=p(g,[["render",b]]);export{y as __pageData,D as default};
